  "claims": [
    {
      "claim": "Lefamulin, a structurally related complex diterpenoid, has absolute oral bioavailability of 25.8% in fasted healthy adults after a 600 mg IR tablet versus IV (C05, C24), and population PK modeling estimates F=0.24 in the fasted state (C33, C40); this directly supports F >= 20% for a similarly complex oxygenated diterpenoid.",
      "card_ids": ["C05", "C24", "C33", "C40"]
    },
    {
      "claim": "BMS-275183, a complex diterpenoid taxane with tert-butyl and multiple ester/lactone motifs, has approximately 24% absolute oral bioavailability in humans (C01, C10, C18), with 50% reported in one source (C50) and 63±7.7% apparent oral bioavailability in mice (C55), supporting transfer of a positive F outcome.",
      "card_ids": ["C01", "C10", "C18", "C50", "C55"]
    },
    {
      "claim": "Tacrolimus, a complex macrocyclic natural product, has about 20% absolute oral bioavailability in fasted humans (C15) and about 25% in transplant recipients (C28, C29, C42); low rat values (C32, C38, C47, C56, C57) are formulation- and species-specific and do not provide affirmative evidence of F < 20% for the query.",
      "card_ids": ["C15", "C28", "C29", "C42", "C32", "C38", "C47", "C56", "C57"]
    },
    {
      "claim": "No L2 record provides affirmative threshold-relevant evidence of F < 20% for a structurally related diterpenoid; the query prior's permeability liability is a physicochemical concern, not an endpoint measurement.",
      "card_ids": ["C05", "C01", "C15"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
